_MAX = 2048

def _pick_sizes(rng: random.Random) -> List[int]:
    # Emphasize interesting sizes
    candidates = [
        0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64,
        127, 128, 255, 256, 511, 512, 1023, 1024, 1500, 1536, 1792, 1900, 2047, 2048
