def _pattern_bytes(length: int, rng: random.Random) -> bytes:
    if length == 0:
        return b""
    # Mix patterns to exercise different memory write behaviors
    pat_choice = rng.randrange(0, 6)
    if pat_choice == 0:
        # All zeros
        return bytes(length)
    elif pat_choice == 1:
        # All 0xFF
        return bytes([0xFF]) * length
    elif pat_choice == 2:
